#!/usr/bin/env python3

# =============================================================================
# Detailed documentation: vcf_filter_merge.py
# Purpose: This script filters single-sample VCF records generated by CLAMMS or
#   CANOES based on caller-specific quality parameters, and merges adjacent
#   or overlapping CNV events of the same type within a specific distance threshold.
# Scope: General pipeline post-processing utility.
# Inputs:
#   - --input_vcf: Input VCF file path.
#   - --output_vcf: Output path for the filtered and merged VCF.
#   - --caller: Caller filter selection (CLAMMS or CANOES).
#   - --distance: Max nucleotide distance to merge adjacent CNVs (default: 1500).
#   - --new_sample: Optional string to rename the sample ID column in the VCF header.
# Outputs:
#   - Merged and sorted VCF file printed to the specified output path.
# Operational notes:
#   - Normalizes copy number state genotype logic to DEL/DUP types.
#   - Applies caller-specific filtering rules (e.g. Q_SOME > 500 & Q_EXACT > 0 for CLAMMS,
#     or Q_SOME > 80 for CANOES).
#   - Merges same-type CNVs within the specified distance limit, retaining the formatting,
#     genotypes, and quality fields of the highest-quality fragment inside the merged group.
#   - Sorts output records numerically by chrom and POS coordinates.
# =============================================================================
import sys
import argparse
import os

def parse_info(info_str):
    """
    Parse a semicolon-separated VCF INFO field string into a dictionary.
    
    Parameters:
    - info_str: Semicolon-delimited INFO field string (e.g., 'END=12345;SVTYPE=DEL').

    Returns:
    - Dict mapping keys to values (boolean True for flag properties).
    """
    info_dict = {}
    for item in info_str.split(';'):
        if not item:
            continue
        if '=' in item:
            k, v = item.split('=', 1)
            info_dict[k] = v
        else:
            info_dict[item] = True
    return info_dict

def build_info(info_dict):
    """
    Serialize an INFO dictionary back into a semicolon-separated string.
    
    Parameters:
    - info_dict: Dict containing parsed key-value properties.

    Returns:
    - Semicolon-separated VCF INFO string.
    """
    parts = []
    for k, v in info_dict.items():
        if v is True:
            parts.append(k)
        else:
            parts.append(f"{k}={v}")
    return ';'.join(parts)

def get_quality_score(var):
    """
    Extract the numeric quality score of a variant record.
    Checks the FORMAT keys for 'Q_SOME' or 'GQ'; otherwise falls back to the QUAL field.
    
    Parameters:
    - var: Dictionary containing parsed VCF record attributes.

    Returns:
    - Float representing the numeric quality score.
    """
    format_keys = var['FORMAT'].split(':')
    format_vals = var['SAMPLE_VALS'].split(':')
    for k, v in zip(format_keys, format_vals):
        if k in ['Q_SOME', 'GQ']:
            try:
                return float(v)
            except ValueError:
                return 0.0
    try:
        return float(var['QUAL']) if var['QUAL'] != '.' else 0.0
    except ValueError:
        return 0.0

def filter_record(var, caller):
    """
    Determine if a record passes the caller-specific quality threshold.
    Also filters out records with null (./.) or reference genotypes (0, 0/0, 0|0).
    
    Parameters:
    - var: Dictionary containing parsed VCF record attributes.
    - caller: String representing the caller name ('CLAMMS' or 'CANOES').

    Returns:
    - True if the record passes quality filters; False otherwise.
    """
    format_keys = var['FORMAT'].split(':')
    format_vals = var['SAMPLE_VALS'].split(':')
    format_dict = dict(zip(format_keys, format_vals))
    
    # Exclude reference or non-called genotypes
    gt = format_dict.get('GT', './.')
    if gt in ['0', '0/0', '0|0']:
        return False
        
    # Apply CLAMMS quality rules (balanced profile: Q_SOME >= 50, Q_EXACT >= 0 for DEL / >= -0.5 for DUP)
    if caller.upper() == 'CLAMMS':
        try:
            q_some = float(format_dict.get('Q_SOME', 0))
            q_exact = float(format_dict.get('Q_EXACT', 0))
            alt_val = var.get('ALT', '')
            min_exact = -0.5 if alt_val == '<DUP>' else 0.0
            return q_some >= 50 and q_exact >= min_exact
        except ValueError:
            return False
        
    # Apply CANOES quality rules (balanced profile: Q_SOME >= 65)
    elif caller.upper() == 'CANOES':
        try:
            q_some = float(format_dict.get('Q_SOME', 0))
            return q_some >= 65
        except ValueError:
            return False
        
    return True

def main():
    """Main execution block to parse input VCF, filter by caller, merge overlapping events, and sort."""
    parser = argparse.ArgumentParser(description="Filter and merge adjacent VCF variants within a sample.")
    parser.add_argument('--input_vcf', required=True, help="Input VCF file path")
    parser.add_argument('--output_vcf', required=True, help="Output VCF file path")
    parser.add_argument('--caller', required=True, choices=['CLAMMS', 'CANOES'], help="Caller name for filtering logic")
    parser.add_argument('--distance', type=int, default=1500, help="Max distance to merge adjacent variants")
    parser.add_argument('--new_sample', help="New sample ID to write in the VCF header")
    args = parser.parse_args()
    
    header_lines = []
    records = []
    
    # Read the input VCF and parse header and individual records
    with open(args.input_vcf, 'r') as f:
        for line in f:
            if line.startswith('#'):
                # Handle #CHROM header line to optionally rename sample ID column
                if line.startswith('#CHROM'):
                    parts = line.strip().split('\t')
                    if args.new_sample and len(parts) >= 10:
                        parts[9] = args.new_sample
                        line = '\t'.join(parts) + '\n'
                header_lines.append(line)
                continue
                
            parts = line.strip().split('\t')
            if len(parts) < 10:
                continue
                
            # Extract standard fields
            chrom = parts[0]
            pos = int(parts[1])
            vid = parts[2]
            ref = parts[3]
            alt = parts[4]
            qual = parts[5]
            filt = parts[6]
            info_str = parts[7]
            fmt = parts[8]
            sample_vals = parts[9]
            
            # Parse END coordinate from INFO field, fallback to POS + len(REF) - 1
            info_dict = parse_info(info_str)
            end_val = info_dict.get('END')
            if end_val is not None:
                end = int(end_val)
            else:
                end = pos + len(ref) - 1
                
            format_keys = fmt.split(':')
            format_vals = sample_vals.split(':')
            format_dict = dict(zip(format_keys, format_vals))
            gt_val = format_dict.get('GT', '0')
            
            # Determine normalized SVTYPE (DEL or DUP) prioritizing ALT allele over GT
            svtype = info_dict.get('SVTYPE', 'CNV')
            if alt == '<DEL>' or alt == 'DEL':
                svtype = 'DEL'
            elif alt == '<DUP>' or alt == 'DUP':
                svtype = 'DUP'
            elif svtype == 'CNV':
                if gt_val == '1':
                    svtype = 'DEL'
                elif gt_val == '2':
                    svtype = 'DUP'
                
            info_dict['SVTYPE'] = svtype
            info_dict['END'] = end
            
            var = {
                'CHROM': chrom,
                'POS': pos,
                'END': end,
                'ID': vid,
                'REF': ref,
                'ALT': alt,
                'QUAL': qual,
                'FILTER': filt,
                'INFO_DICT': info_dict,
                'FORMAT': fmt,
                'SAMPLE_VALS': sample_vals,
                'SVTYPE': svtype
            }
            
            # Filter records by passing them to caller-specific thresholds
            if filter_record(var, args.caller):
                records.append(var)
                
    # Group records by (CHROM, SVTYPE) key for merging
    groups = {}
    for var in records:
        key = (var['CHROM'], var['SVTYPE'])
        if key not in groups:
            groups[key] = []
        groups[key].append(var)
        
    merged_records = []
    
    # Merge events inside each (CHROM, SVTYPE) partition
    for key, var_list in groups.items():
        # Sort variants by start position
        var_list.sort(key=lambda x: x['POS'])
        
        current = None
        for var in var_list:
            if current is None:
                current = var
            else:
                # Calculate gap between adjacent events
                gap = var['POS'] - current['END']
                # If within distance threshold, merge them
                if gap <= args.distance:
                    current['END'] = max(current['END'], var['END'])
                    current['INFO_DICT']['END'] = current['END']
                    
                    # Retain VCF details from the block with higher quality score
                    q_curr = get_quality_score(current)
                    q_var = get_quality_score(var)
                    if q_var > q_curr:
                        current['FORMAT'] = var['FORMAT']
                        current['SAMPLE_VALS'] = var['SAMPLE_VALS']
                        current['QUAL'] = var['QUAL']
                else:
                    merged_records.append(current)
                    current = var
                    
        if current is not None:
            merged_records.append(current)
            
    # Function to sort chromosomes naturally
    def get_sort_key(var):
        chr_name = var['CHROM'].replace('chr', '')
        try:
            return (0, int(chr_name), var['POS'])
        except ValueError:
            return (1, chr_name, var['POS'])
            
    # Sort merged records prior to output writing
    merged_records.sort(key=get_sort_key)
    
    # Write sorted output VCF records
    with open(args.output_vcf, 'w') as out:
        out.writelines(header_lines)
        for var in merged_records:
            # Set SVLEN field based on DEL (-) or DUP (+) type
            svlen = var['END'] - var['POS'] + 1
            if var['SVTYPE'] == 'DEL':
                var['INFO_DICT']['SVLEN'] = -svlen
            else:
                var['INFO_DICT']['SVLEN'] = svlen
                
            info_str = build_info(var['INFO_DICT'])
            
            row = [
                var['CHROM'],
                str(var['POS']),
                var['ID'],
                var['REF'],
                var['ALT'],
                var['QUAL'],
                var['FILTER'],
                info_str,
                var['FORMAT'],
                var['SAMPLE_VALS']
            ]
            out.write('\t'.join(row) + '\n')

if __name__ == '__main__':
    main()

